"""Full-file lessons for pointer arrays, parsers and userspace strings."""
ROWS=[]


def add(path,title,intro,principle,use,sections,questions):
    ROWS.append(dict(path=path,title=title,intro=intro,principle=principle,use=use,
                     area='문자열·파서 · 메모리 수명·경계',sections=sections,questions=questions))


add('lib/memcat_p.c','포인터 배열 병합 전체: NULL 종료와 얕은 복사',
    '두 포인터 배열을 새 배열에 이어 붙입니다. 배열 저장소의 소유권과 가리키는 객체의 소유권을 구분합니다.',
    '__memcat_p는 a와 b를 NULL까지 순회해 원소 수를 합하고 종료 슬롯 하나를 더해 kmalloc_array로 할당합니다. b의 종료 NULL부터 뒤쪽으로 복사하고 b의 시작에 도달하면 a의 끝 원소 쪽으로 전환합니다.',
    'a와 b는 각각 유효한 NULL 종료 포인터 배열이어야 합니다. 빈 배열은 NULL 포인터가 아니라 첫 원소가 NULL인 배열로 전달합니다. 출력 배열은 새로 할당하지만 원소가 가리키는 객체는 복제하지 않습니다.',
    [('파일 전체','SPDX, slab.h 포함, 목적 주석, __memcat_p 함수 하나와 GPL export가 전부입니다. nr은 int이며 두 입력 배열을 셀 때 무한히 큰 배열이나 종료 NULL 누락을 안전하게 검출하는 코드가 없습니다. kmalloc_array는 할당 크기 계산을 돕지만 앞의 잘못된 입력 순회를 복구하지 않습니다.'),
     ('정상 경로 추적','a=[A,B,NULL],b=[C,NULL]이면 두 배열 원소 합 3에 종료 슬롯을 더해 4칸을 할당합니다. p는 b의 NULL을 가리킨 상태이며 new[3]=NULL, new[2]=C를 복사합니다. 그 뒤 p==b 조건으로 a 쪽으로 넘어가 new[1]=B,new[0]=A를 채웁니다. 결과 순서는 입력 a 뒤에 b입니다.'),
     ('빈 입력과 실패','a와 b가 각각 [NULL]이면 한 칸짜리 [NULL] 배열을 새로 만듭니다. b가 비어 있어도 종료 NULL을 먼저 복사한 뒤 a로 전환합니다. 할당 실패 시 NULL을 반환하며 입력 배열은 수정하지 않습니다. GFP_KERNEL 할당을 사용하므로 잠들 수 없는 문맥에서 무조건 안전한 API로 가정하면 안 됩니다.'),
     ('복사·수명·복잡도','원소 수를 합해 n이라 할 때 크기 계산과 복사는 O(n), 출력 저장소는 n+1개의 포인터입니다. 새 배열을 해제해도 A/B/C 객체를 자동 해제하지 않고 입력 객체를 해제하면 새 배열의 포인터도 무효해질 수 있습니다. 객체 소유권 이전·참조 획득은 이 함수에 없습니다.')],
    [('a=[A,B,NULL],b=[C,NULL]의 출력은?', '[A,B,C,NULL]', '[C,A,B,NULL]', '계산은 뒤에서 진행하지만 최종 배치는 a 다음 b입니다. NULL 종료 슬롯을 포함해 네 포인터 칸을 확보합니다.'),
     ('A 객체도 새로 복제되는가?', '아니다. 주소 값만 복사하는 얕은 복사다', '그렇다. 객체 크기를 알아내 깊은 복사한다', '할당 크기는 sizeof(void*)의 배열이며 memcpy나 객체 생성이 아니라 new[nr]=*p 대입입니다. 객체 크기·해제 정책 정보가 없습니다.'),
     ('빈 배열을 a=NULL로 넘겨도 되는가?', '아니다. 첫 원소가 NULL인 유효 배열을 전달해야 한다', '그렇다. 함수가 배열 포인터의 NULL을 먼저 검사한다', '첫 순회 조건이 *p라서 배열 포인터 자체를 역참조합니다. 빈 배열과 배열 주소가 없는 상태는 다릅니다.'),
     ('새 배열 할당에 실패하면 입력 배열 원소가 변경되는가?', '아니다. NULL 반환 전 입력에 쓰는 코드가 없다', '그렇다. 앞에서 일부 원소를 NULL로 바꾼다', '첫 단계는 개수만 읽고 할당 실패 즉시 반환합니다. 실제 쓰기도 성공적으로 할당된 new 배열에만 수행됩니다.')])

add('lib/argv_split.c','argv 분할 전체: 공백 상태 머신과 숨겨진 소유 포인터',
    '단어를 가리키는 포인터 배열과 문자열 저장소를 함께 관리하는 API입니다. 셸 문법 전체를 구현하는 함수는 아닙니다.',
    'count_argc는 공백에서 비공백으로 전환할 때 단어 수를 셉니다. argv_split은 먼저 문자열을 복사하고 argc+2 포인터를 할당합니다. 첫 숨은 슬롯에 문자열 할당 시작 주소를 저장하고 그 다음 칸부터 단어 포인터와 종료 NULL을 구성합니다. argv_free는 반환 포인터를 한 칸 되돌려 두 할당을 해제합니다.',
    '따옴표나 역슬래시를 해석하지 않고 isspace 기준으로만 나눕니다. 성공한 결과는 argv_free로 한 번 해제합니다. 개별 argv[i]는 같은 복사 문자열의 내부 주소이므로 각각 kfree해서는 안 됩니다.',
    [('전체 함수와 파일 구조','SPDX·설명, kernel/ctype/string/slab/export 헤더, 내부 count_argc, 공개 argv_free/argv_split과 각 export가 전체입니다. count_argc는 was_space=true로 시작하고 연속 공백을 하나의 구분 구간으로 처리합니다.'),
     ('복사본을 먼저 만드는 이유','원문은 sysctl 등의 동시 수정 가능성을 언급합니다. kstrndup으로 확보한 로컬 문자열에 대해 단어 수 계산과 실제 분할을 수행하면 이후 두 순회가 같은 저장소를 읽습니다. 복사 도중의 원본 전체가 한 시점의 원자적 스냅샷이었다는 보장까지 생기는 것은 아닙니다.'),
     ('할당과 숨은 슬롯','단어가 2개라면 포인터 4칸입니다. [문자열 시작 주소, 첫 단어, 둘째 단어, NULL]로 구성하고 둘째 칸 주소를 반환합니다. 선행 공백이 있어 argv[0]이 원래 할당 시작과 달라도 숨은 슬롯을 통해 정확한 시작 주소를 해제할 수 있습니다.'),
     ('실패와 빈 문자열','문자열 복사 실패는 NULL 반환입니다. 포인터 배열 할당 실패는 이미 복사한 문자열을 kfree한 뒤 NULL 반환입니다. argcp 대입은 성공 경로 끝에서만 하므로 실패하면 호출자가 갖고 있던 값은 이 함수가 갱신하지 않습니다. 빈 문자열·공백만 있으면 argc=0이고 반환 배열 첫 공개 원소는 NULL입니다.'),
     ('따옴표와 파괴적 분할','복사 문자열의 공백을 NUL로 바꾸어 단어를 끝냅니다. 원본 문자열은 이 코드로 수정하지 않습니다. 입력에 따옴표를 포함한 "a b"가 있으면 두 단어는 따옴표 문자가 남은 "a와 b"가 됩니다. 셸의 하나의 인자 a b와 다릅니다.'),
     ('해제 계약과 CS','argv_free는 먼저 argv--를 하므로 NULL을 그냥 넘겨도 안전한 일반 free wrapper가 아닙니다. 반환 벡터를 임의로 다른 위치로 옮겨 전달하는 것도 계약 위반입니다. sentinel 종료 배열, 상태 머신, interior pointer와 소유 포인터 구분, 실패 시 부분 자원 해제를 연결합니다. n문자와 k단어에 O(n) 시간, 문자열 O(n)+포인터 O(k) 공간입니다.')],
    [('단어가 2개일 때 argc+2 포인터가 필요한 이유는?', '단어 2칸 외에 숨은 문자열 시작 주소와 종료 NULL이 필요하다', '단어마다 문자열을 두 번 저장하기 때문이다', '반환 배열보다 한 칸 앞에 문자열 할당의 실제 시작을 저장합니다. 공개 단어 두 개와 sentinel을 더하면 네 칸입니다.'),
     ('argv[i]를 각각 해제하면 되는가?', '아니다. 공유 문자열 내부 포인터이며 argv_free를 사용한다', '그렇다. 모든 단어가 별도 할당이다', '문자열은 kstrndup 한 번으로 만들고 공백을 NUL로 바꿉니다. 단어 포인터는 그 내부 주소라 개별 해제 대상이 아닙니다.'),
     ('두 번째 할당이 실패하면 첫 문자열 할당은?', '해제한 뒤 NULL을 반환한다', '반환하지 못해도 그대로 남겨둔다', 'kmalloc_array 실패 분기에 kfree(argv_str)가 있습니다. 이 실패 경로는 성공 뒤 argv_free의 두 할당 해제와 별도로 확인해야 합니다.'),
     ('따옴표로 둘러싼 a b는 하나의 인자인가?', '아니다. 공백에서 두 조각으로 나누고 따옴표도 남는다', '그렇다. 셸처럼 따옴표를 해석한다', '함수 문서는 quote processing을 하지 않는다고 명시합니다. 코드도 isspace만 검사하며 quote 상태가 없습니다.')])

add('lib/cmdline.c','명령줄 파서 전체: 정수·범위·단위·옵션·인자 분리',
    '비슷해 보이는 파싱 API도 반환값과 입력 수정 여부가 다릅니다. 이 파일의 여섯 함수를 역할별로 구분합니다.',
    'get_option은 정수와 뒤의 구분자를, get_range/get_options는 정수 목록과 범위를, memparse는 K..E 단위를, parse_option_str은 쉼표 구분 토큰 일치를, next_arg는 따옴표 상태를 고려한 param/value 분리를 담당합니다.',
    '각 함수의 종료 포인터와 출력 계약을 확인합니다. 이들은 모두 엄격한 입력 검증·산술 overflow 검사를 제공하는 범용 보안 파서가 아니며 호출자가 허용 문법·범위·남은 문자열을 확인해야 합니다.',
    [('파일 전체 구성','SPDX·설명·출처·과거 포맷 옵션 주석, export/kernel/string/ctype 헤더, static get_range와 다섯 외부 함수가 전부입니다. get_option,get_options,memparse,next_arg에는 EXPORT_SYMBOL이 있고 parse_option_str에는 이 파일의 export 매크로가 없습니다. 문자열 포인터를 이동시키는 함수와 문자열 바이트 자체를 고치는 next_arg를 구분합니다.'),
     ('get_option의 반환 규약','문자열 포인터가 없거나 빈 문자열이면 0입니다. 부호 -는 별도 처리하고 simple_strtoull로 숫자를 읽어 int에 넣습니다. 숫자 없음 0, 숫자만 1, 쉼표까지 소비 2, 범위를 나타내는 하이픈 앞에서 3입니다. pint가 NULL이어도 파싱할 수 있습니다. 숫자 없는 단독 -는 소비될 수 있고 변환 값을 출력한 뒤 숫자 유무를 확인하므로 실패가 출력 불변을 보장하지는 않습니다.'),
     ('get_range와 정상 목록','범위 하이픈을 넘긴 뒤 상한을 읽고 하한 이상 상한 미만 값을 배열에 채웁니다. 상한 숫자를 가리키는 str은 남겨 다음 get_option이 처리하게 합니다. 1-3,5는 1,2,3,5가 됩니다. ints[0]은 개수 저장에 사용하므로 nints=5일 때 일반 출력 원소 공간은 네 칸입니다. nints=0 검증 모드에서도 ints[0]을 쓰므로 유효한 최소 한 칸이 필요합니다.'),
     ('범위와 용량 경계','get_range의 쓰기 루프는 n으로 제한되지만 반환은 실제 쓴 수가 아니라 upper-lower입니다. 따라서 범위가 남은 공간보다 길면 ints[0]이 실제 저장한 원소 수보다 커질 수 있습니다. 예를 들어 nints=3에서 1-5는 데이터 칸에 1,2만 저장하고 계산된 count는 4가 됩니다. 반환 포인터도 상한 5를 가리킬 수 있습니다. 호출자가 count만 믿고 배열을 넘겨 읽으면 안 됩니다. 큰 signed 범위 차이의 overflow를 일반적으로 검출하는 코드도 없습니다.'),
     ('memparse 단위와 남은 문자','base=0 숫자를 읽고 E/P/T/G/M/K의 대소문자를 받아 10비트 이동을 fallthrough로 누적합니다. K는 2^10, M은 2^20입니다. 2M은 2097152이고 1KB는 K 하나만 소비하므로 retptr이 B를 가리킵니다. unsigned long long 이동·변환의 범위 초과를 명시 오류로 돌려주는 인터페이스가 아닙니다.'),
     ('parse_option_str의 토큰 일치','각 쉼표 구분 위치에서 option 길이만큼 비교하고 그 뒤가 NUL 또는 쉼표인 경우만 true입니다. option=foo는 foobar에 일치하지 않습니다. 공백 trim이나 a=b에서 이름 a만 추출하는 별도 처리는 없으므로 option에 어떤 전체 토큰을 전달하는지 확인합니다.'),
     ('next_arg의 파괴적 분리','따옴표 밖 공백에서 멈추고 첫 유효한 = 위치로 param과 val을 나눕니다. 값의 처음·끝 따옴표를 제거하고 구분 위치를 NUL로 바꾼 뒤 skip_spaces로 다음 인자 위치를 반환합니다. =가 없으면 val=NULL입니다. 역슬래시로 따옴표를 escape하는 문법은 지원하지 않고 따옴표가 닫히지 않았다는 별도 오류 코드도 없습니다. 이름의 -/_ 동등성에 대한 주석이 있지만 이 함수 본문은 해당 문자를 정규화하지 않습니다. 그런 비교는 이후 소비 경로에서 별도로 봐야 합니다.'),
     ('CS 연결','상태 머신·cursor 파싱·sentinel 출력·부분 성공·용량 제한과 보고 개수의 차이를 연결합니다. 단순히 숫자를 얻었다는 사실과 전체 입력을 유효하게 소비했다는 사실은 다릅니다. 함수별 후행 문자 검사와 범위 검증이 API 조합의 핵심입니다.')],
    [('get_option이 숫자 뒤 쉼표까지 소비했을 때 반환값은?', '2', '3', '2는 정수와 쉼표를 함께 읽은 경우이고 3은 범위용 하이픈을 발견한 경우입니다. 두 상황의 다음 포인터 위치가 다릅니다.'),
     ('nints=0 검증 모드에서는 ints=NULL이 허용되는가?', '아니다. 최소 한 칸에 결과 개수를 저장한다', '그렇다. 모든 출력 접근이 생략된다', 'validate 모드에서도 pint로 ints를 사용하고 마지막에 ints[0]=i-1을 수행합니다. 저장 공간이 전혀 필요 없는 모드가 아닙니다.'),
     ('memparse("1KB", &end)의 값과 남은 문자열은?', '1024, end는 B를 가리킨다', '1000, 전체 KB를 모두 소비한다', 'K는 10비트 왼쪽 이동이고 endptr++는 한 글자만 소비합니다. 뒤 B는 파서가 처리하지 않았으므로 호출자가 검사해야 합니다.'),
     ('옵션 foo가 목록 foobar,baz에 존재한다고 판단하는가?', '아니다. 일치 뒤 토큰 경계를 확인한다', '그렇다. 접두부 세 글자가 일치하면 끝이다', 'strncmp 뒤 문자가 NUL 또는 쉼표여야 true입니다. foobar의 다음 b는 경계가 아니므로 거절합니다.'),
     ('next_arg는 원본 문자열을 수정하는가?', '예. =와 구분 공백·일부 따옴표 위치를 NUL로 바꾼다', '아니요. const 입력을 읽기만 한다', '매개변수는 char*이고 args[equals],args[i] 등에 직접 대입합니다. 읽기 전용 문자열 리터럴을 수정 가능한 버퍼처럼 전달하면 안 됩니다.'),
     ('nints=3에 범위 1-5를 넣을 때 ints[0]만 믿고 네 데이터 원소를 읽어도 되는가?', '아니다. 실제 저장 공간 두 칸보다 보고된 범위 개수가 커질 수 있다', '그렇다. 함수가 호출자 배열을 자동 확장한다', 'get_range는 저장을 n으로 제한하지만 upper-lower를 반환해 i를 갱신합니다. 할당이나 배열 확장은 없으므로 저장 용량과 종료 포인터를 함께 확인해야 합니다.')])

add('lib/strncpy_from_user.c','사용자 문자열 복사 전체: count·주소 한계·부분 실패',
    '사용자 주소의 문자열을 커널 버퍼로 복사하면서 fault와 NUL을 다룹니다. libc strncpy와 다른 반환 규약을 갖습니다.',
    'do_strncpy_from_user는 정렬 조건에 맞으면 워드 단위로 읽고 NUL이 있으면 그 뒤 같은 워드의 바이트를 마스크합니다. 워드 읽기 fault나 비효율적인 비정렬 주소에서는 바이트 단위로 전환합니다. 공개 wrapper는 fault 주입·count·사용자 주소 접근 구간을 관리합니다.',
    'dst는 최소 count바이트의 유효 커널 저장소여야 합니다. 성공 길이는 마지막 NUL을 제외합니다. 반환 count는 count만큼 복사했지만 NUL을 확보하지 못했을 수 있는 경우이며, -EFAULT여도 일부 바이트가 이미 복사되었을 수 있습니다.',
    [('파일 전체와 정렬 선택','SPDX, compiler/export/fault-inject/kasan/thread/uaccess/kernel/errno/mm 및 아키텍처 byteorder/word-at-a-time 헤더, IS_UNALIGNED 설정 분기, 내부 복사 함수, 공개 함수·export가 전체입니다. 효율적 비정렬 접근 설정이 있으면 매크로는 0, 없으면 src/dst의 워드 정렬을 검사합니다.'),
     ('워드 경로와 NUL 뒤 마스크','max가 워드 크기 이상일 때 unsafe_get_user로 읽습니다. has_zero→prep_zero_mask→create_zero_mask→zero_bytemask로 처음 NUL 위치와 마스크를 구해 c&mask를 dst에 씁니다. NUL 뒤 같은 워드의 임의 데이터를 그대로 복사하지 않아 문자열을 opaque 바이트 키로 쓰는 BPF 사례의 차이를 줄입니다. 목적지 전체의 나머지 count바이트를 모두 0으로 채운다는 뜻은 아닙니다.'),
     ('바이트 fallback과 제한','워드 읽기 실패는 즉시 최종 실패가 아니라 byte_at_a_time으로 이동합니다. 필요한 짧은 문자열의 앞 바이트는 읽을 수 있는 경우를 처리할 수 있습니다. 바이트 읽기도 실패하면 -EFAULT입니다. NUL을 복사하면 그 위치 res를 길이로 반환하고, max를 다 썼을 때 res>=count면 그 길이, 주소 한계 때문에 더 일찍 끝났다면 -EFAULT입니다.'),
     ('공개 wrapper 순서','might_fault 후 should_fail_usercopy를 먼저 검사해 -EFAULT를 반환할 수 있습니다. 그 다음 count<=0이면 0입니다. masked user access 지원 경로는 begin→내부 복사→end로 처리합니다. 일반 경로는 untagged 주소가 TASK_SIZE_MAX 아래인지 확인하고 max를 주소 공간 잔여량과 count 중 작은 값으로 제한합니다.'),
     ('검사와 접근 구간','일반 경로는 kasan_check_write와 check_object_size로 목적지 범위를 확인한 뒤 user_read_access_begin이 성공하면 내부 함수를 호출합니다. 내부 복사 결과가 실패여도 user_read_access_end를 수행하고 반환합니다. masked 경로에는 이 일반 경로의 목적지 검사 두 줄이 같은 위치에 있지 않으므로 모든 아키텍처 경로가 문장 단위로 동일하다고 설명하지 않습니다.'),
     ('CS와 안정성','사용자 주소 공간 경계·fault 가능한 읽기·partial write·정렬 최적화·byte representation을 연결합니다. 커널에 확보한 결과는 이후 사용자 메모리 변경과 분리되지만 복사 순간 원본 전체가 원자적 snapshot이라는 뜻은 아닙니다. 부분 복사 실패 후 버퍼를 완성된 C 문자열로 사용하지 않아야 합니다.')],
    [('문자열 abc와 NUL을 성공적으로 복사하면 반환 길이는?', '3', '4', '성공값은 NUL을 제외한 문자열 길이입니다. 실제 목적지에는 마지막 NUL까지 복사됩니다. strnlen_user의 NUL 포함 규약과 다릅니다.'),
     ('반환값이 count이면 항상 dst[count-1]이 NUL인가?', '아니다. 제한까지 복사했고 NUL이 없을 수 있다', '그렇다. 항상 마지막 바이트를 NUL로 강제한다', '제한 도달 경로는 기존 복사 길이를 반환하며 별도로 마지막 바이트를 0으로 덮지 않습니다. 호출자는 반환값과 문자열 종료 조건을 함께 확인해야 합니다.'),
     ('워드 단위 사용자 읽기 fault는 즉시 -EFAULT로 끝나는가?', '아니다. 바이트 단위 읽기로 fallback할 수 있다', '그렇다. 바이트 경로는 절대 실행하지 않는다', 'unsafe_get_user 워드 호출의 오류 라벨이 byte_at_a_time입니다. 바이트 읽기 자체가 실패할 때 efault로 갑니다.'),
     ('-EFAULT이면 목적지에 어떤 바이트도 쓰지 않았다고 보장되는가?', '아니다. 일부가 이미 복사되었을 수 있다', '그렇다. 함수가 모든 쓰기를 롤백한다', '원문 문서에 일부 데이터가 복사되었을 수 있다고 명시되어 있습니다. 내부는 순서대로 쓰며 실패 시 이전 쓰기를 되돌리지 않습니다.'),
     ('fault 주입이 활성화된 경우 count<=0이면 무조건 0인가?', '아니다. should_fail_usercopy 검사가 먼저 -EFAULT를 반환할 수 있다', '그렇다. count 검사가 모든 검사보다 먼저다', '공개 함수의 순서는 might_fault, should_fail_usercopy, count<=0입니다. 경계 규칙은 실제 제어 흐름 순서까지 읽어야 합니다.')])

add('lib/strnlen_user.c','사용자 문자열 길이 전체: NUL 포함·초과값·TOCTOU',
    '사용자 메모리의 길이를 먼저 재고 나중에 복사하면 그 사이 내용이 바뀔 수 있습니다. 원문은 이 사용 패턴을 경고합니다.',
    'do_strnlen_user는 시작 주소를 워드 경계 아래로 맞추고 원래 시작 이전 바이트를 1로 가려 잘못된 NUL 감지를 막습니다. 워드별 0바이트를 찾아 NUL을 포함한 길이를 반환합니다. fault는 0, 제한 초과는 count보다 큰 값입니다.',
    '반환 0은 빈 문자열의 길이가 아니라 예외 또는 잘못된 count입니다. 빈 문자열은 정상이라면 1입니다. 길이 초과를 ==count+1로만 검사하지 말고 >count로 검사합니다. 나중에 쓸 문자열은 길이 관찰에 의존하기보다 제한된 복사로 확보하는 것이 원문 권고입니다.',
    [('파일 전체 구성','SPDX, kernel/export/uaccess/mm/bitops/word-at-a-time 헤더, 내부 워드 길이 함수, 공개 wrapper와 export가 전체입니다. 복사 함수와 달리 목적지 버퍼가 없으며 입력 메모리의 바이트만 관찰합니다.'),
     ('정렬과 보정','align은 src 주소의 워드 내 오프셋입니다. src에서 align을 빼고 max에 align을 더해 경계를 맞춥니다. 첫 워드에 aligned_byte_mask(align)을 OR하여 원래 시작 이전 바이트를 0이 아닌 값으로 만듭니다. NUL 위치를 찾으면 res+find_zero+1-align으로 원래 시작 기준이며 NUL 포함인 길이를 계산합니다.'),
     ('왜 count+1만 나오지 않는가','정렬된 워드 하나를 읽으면 그 안에서 사용자 count를 조금 넘는 위치의 NUL도 발견할 수 있습니다. 이때 직접 위치 식으로 반환되어 count+1보다 클 수 있습니다. 워드에서 NUL을 못 찾고 제한을 소진한 별도 경로는 count+1을 반환합니다. 그래서 API 계약은 특정 sentinel 한 값이 아니라 >count입니다.'),
     ('wrapper와 실패','count<=0이면 먼저 0입니다. masked 접근 또는 일반 주소 검증·user_read_access_begin 경로로 내부 함수를 호출하고 접근 종료를 수행합니다. 일반 경로의 max는 TASK_SIZE_MAX와 count로 제한합니다. 읽기 fault나 허용 주소 공간 끝을 너무 일찍 만나는 경우도 0입니다. 사용자 문맥용이며 page fault가 가능하면 잠들 수 있습니다.'),
     ('TOCTOU와 복사 계약','길이 조회 뒤 사용자 스레드가 문자열을 바꿀 수 있어 조회값으로 무제한 후속 복사를 허용하면 안 됩니다. strncpy_from_user 등으로 크기를 제한한 복사본을 얻고 그 반환 규약을 검사합니다. 이 함수의 NUL 포함 길이와 복사 함수의 NUL 제외 성공 길이를 혼동하지 않습니다.'),
     ('CS 연결','정렬 최적화와 추상 API의 관찰 범위, 단일 초과 sentinel과 범위 기반 오류 계약, TOCTOU를 연결합니다. 워드 앞·뒤에 접근 가능한 메모리가 있다는 아키텍처 uaccess 규약을 단순 사용자 공간 strlen과 같은 것으로 대체하지 않습니다.')],
    [('정상적인 빈 사용자 문자열의 반환값은?', '1', '0', '마지막 NUL도 크기에 포함합니다. 반환 0은 예외 또는 count 오류를 나타내므로 정상 빈 문자열과 구별됩니다.'),
     ('길이 초과를 검사하는 올바른 비교는?', '반환값 > count', '반환값 == count+1만', '워드 단위 검색이 count보다 더 뒤의 NUL을 발견하면 count+1보다 큰 실제 위치를 반환할 수 있습니다. 원문은 >count 검사를 요구합니다.'),
     ('길이를 먼저 얻으면 그 길이가 후속 복사 때도 유효하다고 보장되는가?', '아니다. 사용자 메모리가 그 사이 변경될 수 있다', '그렇다. 함수가 사용자 스레드를 계속 정지시킨다', '길이 조회는 영구 잠금이나 snapshot 획득이 아닙니다. 원문은 안정된 복사본을 얻기 위해 strncpy_from_user를 사용하도록 경고합니다.'),
     ('첫 워드에 aligned_byte_mask를 OR하는 이유는?', '원래 시작 주소 이전 바이트에서 NUL을 잘못 찾지 않으려고', '문자열 전체를 0으로 지우려고', '읽기를 정렬하기 위해 주소를 앞당겼으므로 앞의 무관한 바이트를 검색 대상에서 제외해야 합니다. OR한 1비트로 그 바이트들이 0으로 보이지 않게 만듭니다.')])
